#!/usr/bin/env node
// Register the `wtfail://auth` custom-scheme deeplink in the generated Android manifest.
//
// The `android/` tree is created by `npx cap add android` and regenerated by `cap sync`, and it is
// gitignored — so the browser-OAuth return intent-filter cannot live in a committed manifest. This
// script is the committed source of truth instead: it patches the manifest in place, idempotently, and
// is wired into `add:android` / `sync` (see package.json) so a rebuild always re-applies it.
//
// Why a custom scheme (not something Capacitor generates): Capacitor writes a MainActivity with only the
// LAUNCHER intent-filter; a VIEW/BROWSABLE filter for an app-specific scheme is app policy, not framework
// output, so nothing generates it for us. PKCE makes an intercepted deeplink useless (see README).

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, resolve } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const manifestPath = resolve(here, '..', 'android', 'app', 'src', 'main', 'AndroidManifest.xml')

const SCHEME = 'wtfail'
const HOST = 'auth'
const MARKER = 'wtfail deeplink (register-deeplink.mjs)'

const filterBlock = (indent) =>
    `\n${indent}<!-- ${MARKER} -->\n` +
    `${indent}<intent-filter>\n` +
    `${indent}    <action android:name="android.intent.action.VIEW" />\n` +
    `${indent}    <category android:name="android.intent.category.DEFAULT" />\n` +
    `${indent}    <category android:name="android.intent.category.BROWSABLE" />\n` +
    `${indent}    <data android:scheme="${SCHEME}" android:host="${HOST}" />\n` +
    `${indent}</intent-filter>\n`

const manualHint =
    `Add this inside the main <activity> in ${manifestPath}:\n` + filterBlock('  ')

if (!existsSync(manifestPath)) {
    console.error(`[deeplink] No manifest at ${manifestPath}.`)
    console.error(`[deeplink] Run "npx cap add android" first, then re-run "npm run deeplink".`)
    process.exit(1)
}

let xml = readFileSync(manifestPath, 'utf8')

// Idempotent: already registered (by this script or by hand) -> nothing to do.
if (xml.includes(MARKER) || new RegExp(`android:scheme="${SCHEME}"`).test(xml)) {
    console.log(`[deeplink] ${SCHEME}://${HOST} already registered — no change.`)
    process.exit(0)
}

// Locate the MainActivity block (Capacitor's launcher activity) and insert before its </activity>.
const mainIdx = xml.indexOf('.MainActivity')
if (mainIdx < 0) {
    console.error(`[deeplink] Could not find .MainActivity in the manifest.`)
    console.error(manualHint)
    process.exit(1)
}
const closeIdx = xml.indexOf('</activity>', mainIdx)
if (closeIdx < 0) {
    console.error(`[deeplink] Found .MainActivity but no closing </activity>.`)
    console.error(manualHint)
    process.exit(1)
}

// Match the indentation of the </activity> line so the injected block lines up.
const lineStart = xml.lastIndexOf('\n', closeIdx) + 1
const closeIndent = xml.slice(lineStart, closeIdx).match(/^\s*/)[0]
const block = filterBlock(closeIndent + '    ')

xml = xml.slice(0, lineStart) + block + xml.slice(lineStart)
writeFileSync(manifestPath, xml)
console.log(`[deeplink] Registered ${SCHEME}://${HOST} in AndroidManifest.xml.`)
